"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["58661"],{31448(e){e.exports=JSON.parse('{"id":"F260","slug":"position-size-stop-loss","name":"Position Size from a Stop-Loss","subject":"Equity Markets","section":"Equities","topic":"Order types: market, limit, stop","level":"Beginner","aliases":["stop order","risk per trade","stop loss position sizing","order types"],"formula":{"latex":"Q=\\\\frac{A\\\\times r}{P_{entry}-P_{stop}}","also":[],"text":"Shares = (Account size x Risk per trade) / (Entry price - Stop price)"},"symbols":[{"symbol":"Q","meaning":"Number of shares to buy","unit":"number"},{"symbol":"A","meaning":"Account size","unit":"money"},{"symbol":"r","meaning":"Share of the account you accept losing if the stop is hit","unit":"percent"},{"symbol":"P_entry","meaning":"Price you buy at","unit":"money"},{"symbol":"P_stop","meaning":"Price of the stop order that sells if the stock falls to it","unit":"money"}],"when_to_use":"Use it to decide how many shares to buy when you place a stop order. A stop turns into a market order once the price touches it, so the loss is roughly the gap between entry and stop times the shares. Gaps and fast markets can make it worse.","worked_example":{"problem":"A 50,000 account risks 1% on a trade. You buy at 40 with a stop at 37. How many shares?","inputs":{"a":50000,"r":1,"entry":40,"stop":37},"steps":[{"label":"Amount at risk = account x risk","working":"50000 x 0.01","value":"500.00"},{"label":"Shares = risk / (entry - stop), rounded down","working":null,"value":"166"},{"label":"Position cost = shares x entry","working":"166 x 40","value":"6,640.00"},{"label":"Position as a share of the account","working":"6640 / 50000","value":"13.3%"}],"answer":"You can lose 500.00 on the trade, so buy 166 shares. That is a 6,640.00 position, or 13.3% of the account."},"calculator":{"available":true,"inputs":[{"id":"a","label":"Account size","unit":"money","type":"number","default":50000,"hint":""},{"id":"r","label":"Risk per trade","unit":"%","type":"number","default":1,"hint":""},{"id":"entry","label":"Entry price","unit":"money","type":"number","default":40,"hint":""},{"id":"stop","label":"Stop price","unit":"money","type":"number","default":37,"hint":""}],"checks":[{"expr":"entry>stop and stop>0","message":"The stop must be below the entry price and above zero."}],"steps":[{"id":"risk","label":"Amount at risk = account x risk","expr":"a*r","format":"money"},{"id":"q","label":"Shares = risk / (entry - stop), rounded down","expr":"floor(risk/(entry-stop))","format":"num0"},{"id":"cost","label":"Position cost = shares x entry","expr":"q*entry","format":"money"},{"id":"frac","label":"Position as a share of the account","expr":"cost/a","format":"pct1"}],"results":["q","cost"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"risk":500,"q":166,"cost":6640}},"finder":{"finds":"How many shares fit a risk limit","needs":"Account size, risk per trade, entry, stop"},"related":[{"slug":"bid-ask-spread","name":"Bid-Ask Spread and Trading Cost"},{"slug":"margin-call-price","name":"Margin Call Price"}],"related_ids":["F261","F265"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>Q</mi><mo>=</mo><mfrac><mrow><mi>A</mi><mo>\xd7</mo><mi>r</mi></mrow><mrow><msub><mi>P</mi><mrow><mi>e</mi><mi>n</mi><mi>t</mi><mi>r</mi><mi>y</mi></mrow></msub><mo>\u2212</mo><msub><mi>P</mi><mrow><mi>s</mi><mi>t</mi><mi>o</mi><mi>p</mi></mrow></msub></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">Q=\\\\frac{A\\\\times r}{P_{entry}-P_{stop}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"portfolio-variance-matrix","name":"Portfolio Variance in Matrix Form"},"next":{"slug":"ppe-rollforward","name":"PP&E Roll-Forward"},"lesson":null,"total":522}')}}]);